$recent=[]; $groupBy = in_array((string)($_GET['group_by'] ?? 'auto'), ['auto', 'week', 'month'], true) ? (string)($_GET['group_by'] ?? 'auto') : 'auto'; $chartData=build_cashflow_series([], $from, $to, $groupBy); $periodTx=[]; $db_notice=null;
if (!database_ready()) { $db_notice='Your workspace is ready, but the data service is reconnecting. Please refresh shortly.'; }
else { try {
    $daily = db()->prepare("SELECT transaction_date, transaction_type, SUM(amount) total, COUNT(*) n FROM transactions WHERE user_id=:u AND deleted_at IS NULL AND transaction_type IN ('income','expense') AND transaction_date BETWEEN :from AND :to GROUP BY transaction_date, transaction_type");
    $daily->execute(['u'=>$user['id'],'from'=>$from,'to'=>$to]); $dailyRows=$daily->fetchAll();
    foreach ($dailyRows as $row) { if ($row['transaction_type']==='income') $metrics['income']+=(float)$row['total']; else $metrics['expenses']+=(float)$row['total']; $metrics['transactions']+=(int)$row['n']; }
    $metrics['balance'] += $metrics['income'] - $metrics['expenses']; $chartData=build_cashflow_series($dailyRows,$from,$to,$groupBy);
    $p = db()->prepare("SELECT id,transaction_date,description,transaction_type,amount,payment_method FROM transactions WHERE user_id=:u AND deleted_at IS NULL AND transaction_type IN ('income','expense') AND transaction_date BETWEEN :from AND :to ORDER BY transaction_date ASC,id ASC LIMIT 1000"); $p->execute(['u'=>$user['id'],'from'=>$from,'to'=>$to]); $periodTx=$p->fetchAll();
    $r = db()->prepare("SELECT id,transaction_date,description,transaction_type,amount,payment_method FROM transactions WHERE user_id=:u AND deleted_at IS NULL ORDER BY transaction_date DESC,id DESC LIMIT 7"); $r->execute(['u'=>$user['id']]); $recent=$r->fetchAll();
    $q=db()->prepare('SELECT COUNT(*) FROM budgets WHERE user_id=:u'); $q->execute(['u'=>$user['id']]); $metrics['budgets_count']=(int)$q->fetchColumn();
    $q=db()->prepare('SELECT COALESCE(SUM(current_amount),0) FROM savings_goals WHERE user_id=:u'); $q->execute(['u'=>$user['id']]); $metrics['savings_total']=(float)$q->fetchColumn();
    $q=db()->prepare('SELECT COALESCE(SUM(current_balance),0) FROM debts WHERE user_id=:u'); $q->execute(['u'=>$user['id']]); $metrics['debts_total']=(float)$q->fetchColumn();
} catch (Throwable $e) { $db_notice=app_error_message($e); } }
$net=$metrics['income']-$metrics['expenses']; $hasActivity=$metrics['transactions']>0; $healthScore=!$hasActivity?null:min(98,max(45,(int)(65+($net>0?20:-15)+($metrics['savings_total']>1000?10:0))));
$steady=irregular_income_summary((int)$user['id']);
$referenceRates=reference_rates();
$sarbIndicators=$referenceRates['indicators'];
$zarUsdRate=$referenceRates['currency']['rate'];
$chartData['legend']=['income'=>t('cw_income'),'expenses'=>t('cw_expenses'),'profit'=>t('cw_profit')];
$chartDetail=['buckets'=>[],'summary'=>null]; if (database_ready()) { try { $chartDetail=chart_bucket_details(db(),(int)$user['id'],$chartData,(float)($user['opening_balance']??0)); $chartData=chart_attach_details($chartData,$chartDetail); } catch (Throwable $e) { error_log('[Imali Smart] Dashboard chart details failed: '.$e->getMessage()); } }
$runningPath=(float)($user['opening_balance']??0); $balanceSeries=[]; foreach(($chartData['labels']??[]) as $i=>$label){ $runningPath += (float)($chartData['income'][$i]??0) - (float)($chartData['expenses'][$i]??0); $balanceSeries[]=$runningPath; } if ($chartDetail['buckets']) $balanceSeries=array_map(static fn($b)=>(float)$b['balance'],$chartDetail['buckets']); $balanceChart=chart_attach_details(['labels'=>$chartData['labels']??[],'ranges'=>$chartData['ranges']??[],'income'=>$chartData['income']??[],'expenses'=>$chartData['expenses']??[],'profit'=>$balanceSeries,'legend'=>['income'=>'Income','expenses'=>'Expenses','profit'=>'Running balance']],$chartDetail);
$movementChart=['labels'=>['Income','Expenses','Net movement'],'income'=>[$metrics['income'],0,0],'expenses'=>[0,$metrics['expenses'],0],'profit'=>[$metrics['income'], $metrics['expenses'], $net],'legend'=>['income'=>'Income','expenses'=>'Expenses','profit'=>'Net movement']];
// Quick facts shown under the chart: the strongest income period and the heaviest spending period.
$peakIn=null;$peakOut=null;
foreach(($chartData['labels']??[]) as $i=>$lab){ $inV=(float)($chartData['income'][$i]??0); $outV=(float)($chartData['expenses'][$i]??0); if($inV>0&&($peakIn===null||$inV>$peakIn['v']))$peakIn=['l'=>$lab,'v'=>$inV]; if($outV>0&&($peakOut===null||$outV>$peakOut['v']))$peakOut=['l'=>$lab,'v'=>$outV]; }
$keptPct=$metrics['income']>0?(int)round(($net/$metrics['income'])*100):null;
$page_title=t('nav_dashboard'); $page_css='dashboard.css'; $page_js='dashboard.js'; $extra_js=['charts.js']; require __DIR__ . '/includes/header.php';
?>
