'])) ?>"></canvas></div><div class="cash-summary"><div class="cash-pill cash-pill--in"><span>Income</span><strong><?= money($metrics['income']) ?></strong></div><div class="cash-pill cash-pill--out"><span>Expenses</span><strong><?= money($metrics['expenses']) ?></strong></div><div class="cash-pill <?= $net>=0?'cash-pill--in':'cash-pill--out' ?>"><span>Balance</span><strong><?= money($net) ?></strong></div></div><?php if($peakIn||$peakOut||$keptPct!==null): ?><ul class="cash-insights"><?php if($keptPct!==null): ?><li><?= $keptPct>=0?'You kept <strong>'.$keptPct.'%</strong> of what came in.':'You spent <strong>'.abs($keptPct).'%</strong> more than came in.' ?></li><?php endif; ?><?php if($peakIn): ?><li>Most money in: <strong><?= e($peakIn['l']) ?></strong> (<?= money($peakIn['v']) ?>)</li><?php endif; ?><?php if($peakOut): ?><li>Most spent: <strong><?= e($peakOut['l']) ?></strong> (<?= money($peakOut['v']) ?>)</li><?php endif; ?></ul><?php endif; ?></section><aside class="panel"><div class="panel__heading"><div><h2><?= e(t('recent_activity')) ?></h2><p>Your latest personal entries</p></div></div><?php if (!$recent): ?><p class="empty-state">No transactions yet. Add your first entry to start seeing your money clearly.</p><?php else: ?><div class="quick-actions"><?php foreach ($recent as $tx): $in=$tx['transaction_type']==='income'; ?><a class="quick-action" href="transactions.php"><span class="quick-action__icon" style="color:<?= $in?'#16a34a':'#dc2626' ?>;"><?= $in?'+':'-' ?></span><div><strong><?= e((string)$tx['description']) ?></strong><small><?= e(safe_date((string)$tx['transaction_date'])) ?></small></div><span class="<?= $in?'amount-positive':'amount-negative' ?>"><?= $in?'+':'-' ?><?= money((float)$tx['amount']) ?></span></a><?php endforeach; ?></div><?php endif; ?></aside></div>
